const rulesCatalog = () => RULES.map(({ id, severity, title, why, fix }) => ({ id, severity, title, why, fix }));

// ---------------- report ----------------

class Report {
  constructor(pipeline) { this.pipeline = pipeline; this.findings = []; this.notes = []; }
  add(id, severity, title, why, fix, evidence = "") { this.findings.push({ id, severity, title, why, fix, evidence }); }
  get score() { return Math.min(100, this.findings.reduce((a, f) => a + WEIGHT[f.severity], 0)); }
  sorted() { return [...this.findings].sort((a, b) => SEVERITY_ORDER[a.severity] - SEVERITY_ORDER[b.severity]); }
  markdown(footer) {
    const fs = this.sorted();
    const out = [`# Lead leak risk: ${this.pipeline}`, "", `Risk score: **${this.score}/100** (${fs.length} findings)`, ""];
    if (!fs.length) out.push("No leak risks found in the information given.");
    fs.forEach((f, i) => {
      out.push(`## ${i + 1}. [${f.severity.toUpperCase()}] ${f.title}`, `- Why it leaks: ${f.why}`, `- Fix: ${f.fix}`);
      if (f.evidence) out.push(`- Evidence: ${f.evidence}`);
      out.push("");
    });
    for (const n of this.notes) out.push(`> ${n}`);
    if (footer) out.push("", footer);
    return out.join("\n").trim() + "\n";
  }
  asDict({ footer = "_Generated by lead-leak-check (MIT)._" } = {}) {
    const fs = this.sorted();
    const counts = {};
    for (const s of Object.keys(SEVERITY_ORDER)) counts[s] = fs.filter((f) => f.severity === s).length;
    return { pipeline: this.pipeline, risk_score: this.score, counts, findings: fs, notes: this.notes, report_markdown: this.markdown(footer) };
  }
}

function checkConfig(cfg) {
  if (!isDict(cfg)) throw new InputError("pipeline config must be a JSON object");
  const rep = new Report(pyStr(pyBool(cfg.name) ? cfg.name : "unnamed pipeline"));
  let unknown = 0;
  for (const r of RULES) {
    const state = r.check(cfg);
    if (state === true) continue;
    if (state === false) rep.add(r.id, r.severity, r.title, r.why, r.fix);
    else { unknown++; rep.add(r.id, "verify", `Not stated: ${r.title.toLowerCase()}`, r.why, r.fix); }
  }
  if (unknown) rep.notes.push(`${unknown} safeguard(s) were not described; they are listed as 'verify'. Fill them in for a sharper result.`);
  return rep;
}

